CREATE TABLE IF NOT EXISTS workflows (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES agents(id), active_version INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 0, interval_hours INTEGER NOT NULL DEFAULT 24, max_daily_runs INTEGER NOT NULL DEFAULT 1, next_at BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'idle');
CREATE TABLE IF NOT EXISTS workflow_versions (workflow_id BIGINT NOT NULL REFERENCES workflows(id), number INTEGER NOT NULL, name TEXT NOT NULL, objective TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(workflow_id,number));
CREATE TABLE IF NOT EXISTS workflow_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workflow_id BIGINT NOT NULL REFERENCES workflows(id), version INTEGER NOT NULL, conversation_id BIGINT REFERENCES conversations(id), status TEXT NOT NULL, result TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);

ALTER TABLE workflows ENABLE ROW LEVEL SECURITY;
ALTER TABLE workflow_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE workflow_runs ENABLE ROW LEVEL SECURITY;
